from abc import ABCMeta, abstractmethod
from six import with_metaclass


class Catalog(with_metaclass(ABCMeta, object)):
    @abstractmethod
    def get_info(self, api_version=None):
        raise NotImplementedError

    @abstractmethod
    def post_info(self, path, api_version=None):
        raise NotImplementedError

    @abstractmethod
    def delete_info(self, vnfd_id, api_version=None):
        raise NotImplementedError
